package com.projectdark.mobile;
import android.content.Context;
import android.graphics.*;
import com.projectdark.mobile.world.*;
import org.json.*;
import java.io.*;
import java.util.*;
/** Native tiles/objects/actors, bounded32-chunk LRU and prewarmed exact-alpha monster variants. */
public final class CountessCastleRenderer {
 private static final float SCALE=8f/7f;
 private final Context context;private final Paint paint=new Paint();private final Rect clip=new Rect(),src=new Rect();private final RectF dst=new RectF();
 private final Map<Integer,Bitmap> floors=new HashMap<>(),objects=new HashMap<>();private final LinkedHashMap<Long,Bitmap> chunks=new LinkedHashMap<>(32,.75f,true);
 private final List<Piece> foreground=new ArrayList<>();private final List<PoteFieldRenderer.ActorDraw> actors=new ArrayList<>();
 private final Bitmap[][] sheets=new Bitmap[4][14];private final int[][] meta=new int[14][9];private String map;private HorrorCastleOriginalData.Grid grid;private int builds;
 private static final class Piece {final Bitmap b;final float x,y,depth;Piece(Bitmap b,float x,float y,float depth){this.b=b;this.x=x;this.y=y;this.depth=depth;}}
 public CountessCastleRenderer(Context c){context=c;paint.setFilterBitmap(false);try(InputStream in=c.getAssets().open("countess-v273/manifest.json")){JSONArray a=new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("monsters");for(int t=0;t<14;t++){JSONObject m=a.getJSONObject(t);String[] keys={"width","height","anchorX","anchorY","idle","idleCount","walk","walkCount","attack"};for(int k=0;k<keys.length;k++)meta[t][k]=m.getInt(keys[k]);attackCounts[t]=m.getInt("attackCount");}}catch(Exception e){throw new IllegalStateException("Countess source metadata",e);}}
 private final int[] attackCounts=new int[14];
 private Bitmap load(String name){try(InputStream in=context.getAssets().open("countess-v273/"+name+".png")){BitmapFactory.Options o=new BitmapFactory.Options();o.inScaled=false;Bitmap b=BitmapFactory.decodeStream(in,null,o);if(b==null)throw new IOException(name);b.prepareToDraw();return b;}catch(Exception e){throw new IllegalStateException("Missing Countess original "+name,e);}}
 public void release(){chunks.clear();floors.clear();objects.clear();foreground.clear();actors.clear();for(Bitmap[] a:sheets)Arrays.fill(a,null);map=null;grid=null;}
 public void prepare(String id){if(id.equals(map))return;release();map=id;grid=CountessCastleData.grid(id);if(grid==null)throw new IllegalArgumentException(id);Set<Integer> types=new HashSet<>();for(int t:CountessCastleMonsters.roster(id))types.add(t);if(CountessCastleGeometry.EXTERIOR.equals(id))types.add(0);
  for(int t:types){sheets[0][t]=load("monster_"+t);for(int v=1;v<4;v++){sheets[v][t]=MonsterCursePalette.variant(sheets[0][t],v>=2,(v&1)!=0);sheets[v][t].prepareToDraw();}}
  for(int v=0;v<grid.height;v++)for(int u=0;u<grid.width;u++){int bg=grid.value(u,v,0);if(bg>0&&!floors.containsKey(bg))floors.put(bg,load("bg"+bg));for(int side=1;side<=2;side++){int n=grid.value(u,v,side);if(n<=12)continue;Bitmap b=objects.get(n);if(b==null){b=load(String.format(Locale.ROOT,"stc%05d",n));objects.put(n,b);}float foot=CountessCastleGeometry.y(u,v)+16;foreground.add(new Piece(b,CountessCastleGeometry.x(u,v)-32+(side-1)*32,foot-b.getHeight()*SCALE,foot));}}foreground.sort(Comparator.comparingDouble(a->a.depth));
 }
 private Bitmap chunk(int cx,int cy){long k=((long)cx<<32)^(cy&0xffffffffL);Bitmap found=chunks.get(k);if(found!=null)return found;Bitmap b=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.BLACK);float left=cx*256f,top=cy*256f;for(int v=0;v<grid.height;v++)for(int u=0;u<grid.width;u++){float x=CountessCastleGeometry.x(u,v)-32,y=CountessCastleGeometry.y(u,v)-16;if(x+64<left||x>left+256||y+32<top||y>top+256)continue;Bitmap tile=floors.get(grid.value(u,v,0));if(tile!=null){dst.set(x-left,y-top,x-left+64,y-top+27*SCALE);c.drawBitmap(tile,null,dst,paint);}}b.prepareToDraw();chunks.put(k,b);builds++;if(chunks.size()>32){Iterator<Long> it=chunks.keySet().iterator();it.next();it.remove();}return b;}
 private void piece(Canvas c,Piece a,float ox,float oy){float w=a.b.getWidth()*SCALE,h=a.b.getHeight()*SCALE;if(a.x+w<ox+clip.left||a.x>ox+clip.right||a.y+h<oy+clip.top||a.y>oy+clip.bottom)return;dst.set(a.x-ox,a.y-oy,a.x-ox+w,a.y-oy+h);c.drawBitmap(a.b,null,dst,paint);}
 public void draw(Canvas c,WorldRuntimeAdapter world,List<PoteFieldRenderer.ActorDraw> input){prepare(world.runtime().currentMapId());float ox=world.camera().cameraX(),oy=world.camera().cameraY();c.getClipBounds(clip);paint.setColor(Color.WHITE);paint.setAlpha(255);for(int cy=(int)Math.floor((oy+clip.top)/256f);cy<=Math.floor((oy+clip.bottom)/256f);cy++)for(int cx=(int)Math.floor((ox+clip.left)/256f);cx<=Math.floor((ox+clip.right)/256f);cx++)c.drawBitmap(chunk(cx,cy),cx*256f-ox,cy*256f-oy,paint);actors.clear();actors.addAll(input);actors.sort(Comparator.comparingDouble(a->a.y));int i=0;for(PoteFieldRenderer.ActorDraw actor:actors){while(i<foreground.size()&&foreground.get(i).depth<=actor.y)piece(c,foreground.get(i++),ox,oy);actor.draw.run();}while(i<foreground.size())piece(c,foreground.get(i++),ox,oy);actors.clear();for(CountessCastleGeometry.Gate g:CountessCastleGeometry.gates(map)){UiTheme.center(c,g.label,g.x-ox,g.y-oy-26,9,0xfff0dfb9,true);}}
 public void monster(Canvas c,RuntimeState.Monster m,SkillEffectState fx){int t=CountessCastleMonsters.type(m.id);boolean attack=m.attackPrimed||m.attackVisualRemaining>0;float clock=attack?Math.max(0,.6f-m.attackVisualRemaining):m.animationClock;pose(c,t,m.x,m.y,m.visualFacing.presentation(),m.isMoving,attack,clock,(MonsterCursePalette.active(fx,m.id)?2:0)+(m.hitFlash>0?1:0));}
 public void envoy(Canvas c,float x,float y){pose(c,0,x,y,CharacterRenderer.Direction.SW,false,false,0,0);}
 private void pose(Canvas c,int t,float x,float y,CharacterRenderer.Direction d,boolean moving,boolean attack,float clock,int variant){if(t<0||sheets[variant][t]==null)return;int[] m=meta[t];int view=d==CharacterRenderer.Direction.NW||d==CharacterRenderer.Direction.NE?0:1;boolean flip=d==CharacterRenderer.Direction.NW||d==CharacterRenderer.Direction.SW;int count=attack?attackCounts[t]:moving?m[7]:m[5];int start=attack?m[8]:moving?m[6]:m[4];if(count==0){start=m[4];count=m[5];}int frame=start+view*count+(int)(clock/.12f)%Math.max(1,count);if(t==4)frame=0;int w=m[0],h=m[1];src.set(frame%4*w,frame/4*h,frame%4*w+w,frame/4*h+h);c.save();if(flip)c.scale(-1,1,x,y);dst.set(x-m[2]*SCALE,y-m[3]*SCALE,x+(w-m[2])*SCALE,y+(h-m[3])*SCALE);c.drawBitmap(sheets[variant][t],src,dst,paint);c.restore();}
 public float bodyHeight(String id){int t=CountessCastleMonsters.type(id);return t<0?60:meta[t][3]*SCALE;}
 public int floorEntries(){return chunks.size();}public int floorBuilds(){return builds;}public long floorBytes(){long n=0;for(Bitmap b:chunks.values())n+=b.getAllocationByteCount();return n;}public long atlasBytes(){long n=0;for(Bitmap[] v:sheets)for(Bitmap b:v)if(b!=null)n+=b.getAllocationByteCount();return n;}
}
